        private void CheckAlarm(int nBitLength, Dictionary<int, bool> dicAlarms)
        {
            Dictionary<int, bool> dicAlarms_old = null;

            // 비교 후 알람 발생 및 해제 
            if (nBitLength >= m_nLength1)            
                dicAlarms_old = m_dicAlarms1;            
            else if (nBitLength >= m_nLength2)            
                dicAlarms_old = m_dicAlarms2;            
            else if (nBitLength >= m_nLength3)            
                dicAlarms_old = m_dicAlarms3;            
            else if (nBitLength >= m_nLength4)            
                dicAlarms_old = m_dicAlarms4;            
            else if (nBitLength >= m_nLength5)            
                dicAlarms_old = m_dicAlarms5;            
            else if (nBitLength >= m_nLength6)            
                dicAlarms_old = m_dicAlarms6;            
            else if (nBitLength >= m_nLength7)            
                dicAlarms_old = m_dicAlarms7;            
            else if (nBitLength >= m_nLength8)            
                dicAlarms_old = m_dicAlarms8;            
            else if (nBitLength >= m_nLength9)            
                dicAlarms_old = m_dicAlarms9;            
            else
                return;

            if (CompareAlarms(dicAlarms_old, dicAlarms, out Dictionary<int, bool> addAlarms, out Dictionary<int, bool> removeAlarms, out string strErrorMessage))
            {
                // 알람 해제
                foreach (KeyValuePair<int, bool> pair in removeAlarms)
                {
                    int nTag = pair.Key;
                    Logger.Instance.Write($"FireProvider 알람 해제 TagNo: {nTag}");

                    // 알람 정보 불러오기
                    if (m_parent.SensorManager.FireSensors.ContainsKey(nTag))
                    {
                        SensorData sensor = m_parent.SensorManager.FireSensors[nTag];

                        ArrayList arrData = new ArrayList();
                        arrData.Add(sensor.SensorType);
                        arrData.Add(sensor.TagID);
                        arrData.Add(sensor.SensorZoneID);
                        arrData.Add(false);

                        // 알람 해제 신호
                        if (m_sopQueryMgr.SendAlarmQuery(arrData, ID.ALARM_METHOD, m_strSOPWebServerURL) == false)                        
                            Logger.Instance.Write($"FireProvider SendAlarmQuery() Error (IsAlarm: {false}, TagID: {sensor.TagID}, SensorZoneID: {sensor.SensorZoneID})");                        
                        else                        
                            dicAlarms_old.Remove(nTag);                        
                    }
                }

                // 알람 발생
                foreach (KeyValuePair<int, bool> pair in addAlarms)
                {
                    int nTag = pair.Key;
                    Logger.Instance.Write($"FireProvider 알람 발생 TagNo: {nTag}");

                    // 알람 정보 불러오기
                    if (m_parent.SensorManager.FireSensors.ContainsKey(nTag))
                    {
                        SensorData sensor = m_parent.SensorManager.FireSensors[nTag];

                        ArrayList arrData = new ArrayList();
                        arrData.Add(sensor.SensorType);
                        arrData.Add(sensor.TagID);
                        arrData.Add(sensor.SensorZoneID);
                        arrData.Add(true);

                        // 알람 발생 신호
                        if (m_sopQueryMgr.SendAlarmQuery(arrData, ID.ALARM_METHOD, m_strSOPWebServerURL) == false)
                            Logger.Instance.Write($"FireProvider SendAlarmQuery() Error (IsAlarm: {true}, TagID: {sensor.TagID}, SensorZoneID: {sensor.SensorZoneID})");
                        else
                            dicAlarms_old.Add(nTag, true);
                    }
                }
            }
        }

        private bool CompareAlarms(Dictionary<int, bool> dicAlarms_old, Dictionary<int, bool> dicAlarms_new, out Dictionary<int, bool> addAlarms, out Dictionary<int, bool> removeAlarms, out string strErrorMessage)
        {
            strErrorMessage = "";

            addAlarms = new Dictionary<int, bool>();
            removeAlarms = new Dictionary<int, bool>();

            foreach (KeyValuePair<int, bool> pair in dicAlarms_new)
            {
                int nTag = pair.Key;

                if (dicAlarms_old.ContainsKey(nTag) == false)
                    addAlarms.Add(nTag, true);
            }

            foreach (KeyValuePair<int, bool> pair in dicAlarms_old)
            {
                int nTag = pair.Key;

                if (dicAlarms_new.ContainsKey(nTag) == false)
                    removeAlarms.Add(nTag, true);
            }

            return true;
        }

        public void RequestFireData()
        {
            try
            {
                if (!this.IsConnected)
                    return;

                UInt16 nStartAddr = 0;      // 시작 주소 (0 또는 1)
                byte[] arrData = ModbusHelper.MakeRequestMsg(ModbusHelper.FC_ReadDiscrete, m_nSlaveID, m_nTransID, nStartAddr, m_nLength1);
                SendBytes(arrData);                    
                if (m_parent.DelayThread(m_nRequestDelay) == false)
                    return;
                m_nTransID++;

                if (!this.IsConnected)
                    return;

                nStartAddr = (UInt16)(nStartAddr + m_nLength1);
                arrData = ModbusHelper.MakeRequestMsg(ModbusHelper.FC_ReadDiscrete, m_nSlaveID, m_nTransID, nStartAddr, m_nLength2);
                SendBytes(arrData);                    
                if (m_parent.DelayThread(m_nRequestDelay) == false)
                    return;
                m_nTransID++;

                if (!this.IsConnected)
                    return;

                nStartAddr = (UInt16)(nStartAddr + m_nLength1 + m_nLength2);
                arrData = ModbusHelper.MakeRequestMsg(ModbusHelper.FC_ReadDiscrete, m_nSlaveID, m_nTransID, nStartAddr, m_nLength3);
                SendBytes(arrData);                    
                if (m_parent.DelayThread(m_nRequestDelay) == false)
                    return;
                m_nTransID++;

                if (!this.IsConnected)
                    return;

                nStartAddr = (UInt16)(nStartAddr + m_nLength1 + m_nLength2 + m_nLength3);
                arrData = ModbusHelper.MakeRequestMsg(ModbusHelper.FC_ReadDiscrete, m_nSlaveID, m_nTransID, nStartAddr, m_nLength4);
                SendBytes(arrData);                    
                if (m_parent.DelayThread(m_nRequestDelay) == false)
                    return;
                m_nTransID++;

                if (!this.IsConnected)
                    return;

                nStartAddr = (UInt16)(nStartAddr + m_nLength1 + m_nLength2 + m_nLength3 + m_nLength4);
                arrData = ModbusHelper.MakeRequestMsg(ModbusHelper.FC_ReadDiscrete, m_nSlaveID, m_nTransID, nStartAddr, m_nLength5);
                SendBytes(arrData);                    
                if (m_parent.DelayThread(m_nRequestDelay) == false)
                    return;
                m_nTransID++;

                if (!this.IsConnected)
                    return;

                nStartAddr = (UInt16)(nStartAddr + m_nLength1 + m_nLength2 + m_nLength3 + m_nLength4 + m_nLength5);
                arrData = ModbusHelper.MakeRequestMsg(ModbusHelper.FC_ReadDiscrete, m_nSlaveID, m_nTransID, nStartAddr, m_nLength6);
                SendBytes(arrData);                    
                if (m_parent.DelayThread(m_nRequestDelay) == false)
                    return;
                m_nTransID++;

                if (!this.IsConnected)
                    return;

                nStartAddr = (UInt16)(nStartAddr + m_nLength1 + m_nLength2 + m_nLength3 + m_nLength4 + m_nLength5 + m_nLength6);
                arrData = ModbusHelper.MakeRequestMsg(ModbusHelper.FC_ReadDiscrete, m_nSlaveID, m_nTransID, nStartAddr, m_nLength7);
                SendBytes(arrData);                    
                if (m_parent.DelayThread(m_nRequestDelay) == false)
                    return;
                m_nTransID++;

                if (!this.IsConnected)
                    return;

                nStartAddr = (UInt16)(nStartAddr + m_nLength1 + m_nLength2 + m_nLength3 + m_nLength4 + m_nLength5 + m_nLength6 + m_nLength7);
                arrData = ModbusHelper.MakeRequestMsg(ModbusHelper.FC_ReadDiscrete, m_nSlaveID, m_nTransID, nStartAddr, m_nLength8);
                SendBytes(arrData);                    
                if (m_parent.DelayThread(m_nRequestDelay) == false)
                    return;
                m_nTransID++;

                if (!this.IsConnected)
                    return;

                nStartAddr = (UInt16)(nStartAddr + m_nLength1 + m_nLength2 + m_nLength3 + m_nLength4 + m_nLength5 + m_nLength6 + m_nLength7 + m_nLength8);
                arrData = ModbusHelper.MakeRequestMsg(ModbusHelper.FC_ReadDiscrete, m_nSlaveID, m_nTransID, nStartAddr, m_nLength9);
                SendBytes(arrData);                    
                if (m_parent.DelayThread(m_nRequestDelay) == false)
                    return;
                m_nTransID++;              
            }
            catch (Exception e)
            {
                Logger.Instance.Write("FireProvider RequestFireData() Error : " + e.Message);
            }
        }

        public void SendBytes(byte[] CmdBuff)
        {
            try
            {
                if (!this.IsClientDisposed && this.IsConnected)
                {
                    this.LengthAdd = false;
                    int nResult = this.Send(CmdBuff, 0, CmdBuff.Length);

                    if (nResult < 0)
                    {
                        lock (this)
                        {
                            if (this.IsConnected)
                                this.Close();

                            if (this.Client.Client != null)
                            {
                                if (this.Client.Connected)
                                    this.Client.Close();
                            }
                        }
                    }                    
                }
            }
            catch (Exception e)
            {
                Logger.Instance.Write("FireProvider SendBytes() Error: " + e.Message);
            }
        }
    }
}

